def enrich(orders, customers, blocked):
    # customers: list[Customer], blocked: list[str]
    out = []
    for order in orders:                              # n
        customer = next(c for c in customers          # x m  -> O(n*m)
                        if c.id == order.customer_id)
        if order.email in blocked:                    # x b  -> O(n*b)
            continue
        out.append((order, customer))
    return out

# O(n*(m + b)). Two index builds make it O(n + m + b):
def enrich_fast(orders, customers, blocked):
    by_id = {c.id: c for c in customers}
    blocked_set = set(blocked)
    return [(o, by_id[o.customer_id]) for o in orders
            if o.email not in blocked_set]

import timeit

def cost(fn, n):
    return timeit.timeit(lambda: fn(n), number=3)

quadratic = lambda n: sum(1 for i in range(n) if i in list(range(n)))
linear = lambda n: sum(1 for i in range(n) if i in set(range(n)))

for fn, label in ((quadratic, "quadratic"), (linear, "linear")):
    small, large = cost(fn, 1000), cost(fn, 4000)
    # 4x the input: ~4x for linear, ~16x for quadratic.
    print(f"{label}: {large / small:.1f}x for 4x input")
